WITH exploded AS (SELECT id, service, status_code, attr_key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS attr_key, v) SELECT id, service, RANK() OVER w_grp AS status_code_rank, RANK() OVER (ORDER BY status_code) AS status_code_rank_2, CUME_DIST() OVER (PARTITION BY service ORDER BY status_code) AS status_code_cume_dist FROM exploded WHERE attr_key != 'trace' WINDOW w_grp AS (PARTITION BY attr_key ORDER BY status_code DESC);
